<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Stock History</h1><a class="btn btn-outline-secondary" href="<?= url_to('admin.inventory') ?>">Back</a></div><div class="card border-0"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Type</th><th>Change</th><th>Before</th><th>After</th><th>Note</th><th>Admin</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= esc($m['created_at']) ?></td><td><?= esc($m['movement_type']) ?></td><td><?= (int)$m['quantity'] ?></td><td><?= (int)$m['quantity_before'] ?></td><td><?= (int)$m['quantity_after'] ?></td><td><?= esc($m['note']) ?></td><td><?= esc($m['admin_name']??'System') ?></td></tr><?php endforeach ?><?php if(!$movements): ?><tr><td colspan="7" class="text-center text-muted py-4">No stock movements yet.</td></tr><?php endif ?></tbody></table></div></div><?= $this->endSection() ?>
